import sys
input = sys.stdin.read

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a // gcd(a, b) * b

def solve():
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:]))

    prefix_gcd = [0] * n
    suffix_gcd = [0] * n

    prefix_gcd[0] = a[0]
    for i in range(1, n):
        prefix_gcd[i] = gcd(prefix_gcd[i-1], a[i])

    suffix_gcd[n-1] = a[n-1]
    for i in range(n-2, -1, -1):
        suffix_gcd[i] = gcd(suffix_gcd[i+1], a[i])

    valid_ways = 0

    for x in range(n):
        if gcd(prefix_gcd[x], k) == k:
            valid_ways += 1
            continue

        if x < n-1 and gcd(lcm(prefix_gcd[x], suffix_gcd[x+1]), k) == k:
            valid_ways += 1

    print(valid_ways)

solve()

